create or replace function public.create_invoice_transaction(p_booking_id uuid,p_status text default 'DRAFT') returns jsonb language plpgsql security definer set search_path=public as $$ declare b public.bookings%rowtype; invoice_id uuid; invoice_number text; seq bigint; current_year text:=to_char(current_date,'YYYY'); begin if not public.has_permission('invoices','create') and public.staff_role()<>'ADMIN' then raise exception 'Not authorized to create invoices' using errcode='42501'; end if; if p_status not in ('DRAFT','ISSUED','PARTIALLY_PAID','PAID','OVERDUE','CANCELLED') then raise exception 'Invalid invoice status' using errcode='22023'; end if; if upper(p_status)<>'DRAFT' then perform public.require_finance_aal2(); end if; select * into b from public.bookings where id=p_booking_id for update; if not found or not public.row_in_staff_scope(b.agency_id,coalesce(b.branch_id,b.branch_uuid)) then raise exception 'Booking not found in staff scope' using errcode='42501'; end if; perform pg_advisory_xact_lock(hashtext('invoice-number:'||current_year)); select coalesce(max(nullif(regexp_replace(invoice_number,'^INV-'||current_year||'-','')::text,'')::bigint),0)+1 into seq from public.invoices where invoice_number like 'INV-'||current_year||'-%'; invoice_number:='INV-'||current_year||'-'||lpad(seq::text,6,'0'); insert into public.invoices(agency_id,branch_id,booking_id,invoice_number,total_dzd,total_sar,status,issued_at) values(b.agency_id,coalesce(b.branch_id,b.branch_uuid),b.id,invoice_number,coalesce(b.total_dzd,0),coalesce(b.total_sar,0),upper(p_status),case when upper(p_status)='DRAFT' then null else now() end) returning id into invoice_id; return jsonb_build_object('invoice_id',invoice_id,'invoice_number',invoice_number,'booking_id',b.id); exception when unique_violation then raise exception 'Invoice number collision; retry transaction' using errcode='40001'; end; $$;

create or replace function public.reverse_payment_transaction(p_payment_id uuid,p_amount_dzd numeric default null,p_amount_sar numeric default null,p_reason text default 'Payment reversal') returns jsonb language plpgsql security definer set search_path=public as $$ declare p public.payments%rowtype; b public.bookings%rowtype; reversal_id uuid; rdzd numeric; rsar numeric; already_dzd numeric; already_sar numeric; new_paid_dzd numeric; new_paid_sar numeric; begin perform public.require_finance_aal2(); select * into p from public.payments where id=p_payment_id for update; if not found then raise exception 'Payment not found' using errcode='22023'; end if; if not public.has_permission('payments','create') and public.staff_role()<>'ADMIN' then raise exception 'Not authorized to reverse payments' using errcode='42501'; end if; if not public.row_in_staff_scope(p.agency_id,coalesce(p.branch_id,p.branch_uuid)) then raise exception 'Payment not in staff scope' using errcode='42501'; end if; if p.status<>'CONFIRMED' then raise exception 'Only confirmed payments can be reversed' using errcode='22023'; end if; select coalesce(sum(amount_dzd),0),coalesce(sum(amount_sar),0) into already_dzd,already_sar from public.payment_reversals where payment_id=p.id and status='CONFIRMED'; rdzd:=coalesce(p_amount_dzd,p.amount_dzd)-already_dzd; rsar:=coalesce(p_amount_sar,p.amount_sar)-already_sar; if rdzd<0 or rsar<0 or (rdzd=0 and rsar=0) then raise exception 'Reversal exceeds unreversed payment balance' using errcode='22023'; end if; if p.booking_id is not null then select * into b from public.bookings where id=p.booking_id for update; if not found then raise exception 'Booking not found' using errcode='22023'; end if; if not public.row_in_staff_scope(b.agency_id,coalesce(b.branch_id,b.branch_uuid)) then raise exception 'Booking not in staff scope' using errcode='42501'; end if; end if; insert into public.payment_reversals(agency_id,branch_id,payment_id,booking_id,amount_dzd,amount_sar,reason,reference,created_by) values(p.agency_id,coalesce(p.branch_id,p.branch_uuid),p.id,p.booking_id,rdzd,rsar,nullif(trim(p_reason),''),'REV-'||replace(gen_random_uuid()::text,'-',''),auth.uid()) returning id into reversal_id; if p.booking_id is not null then new_paid_dzd:=greatest(0,coalesce(b.paid_dzd,0)-rdzd); new_paid_sar:=greatest(0,coalesce(b.paid_sar,0)-rsar); update public.bookings set paid_dzd=new_paid_dzd,paid_sar=new_paid_sar,status=case when new_paid_dzd=0 and new_paid_sar=0 then 'CONFIRMED' when new_paid_dzd<coalesce(b.total_dzd,0) or new_paid_sar<coalesce(b.total_sar,0) then 'PARTIAL' else status end,updated_at=now() where id=b.id; end if; return jsonb_build_object('reversal_id',reversal_id,'payment_id',p.id,'amount_dzd',rdzd,'amount_sar',rsar); end; $$;

create or replace function public.post_invoice_journal(p_invoice_id uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare i public.invoices%rowtype; je uuid; ar uuid; rev uuid; fp uuid; ref text; begin perform public.require_finance_aal2(); select * into i from public.invoices where id=p_invoice_id for update; if not found or not public.row_in_staff_scope(i.agency_id,coalesce(i.branch_id,i.branch_uuid)) then raise exception 'Invoice not in scope' using errcode='42501'; end if; fp:=public.assert_open_fiscal_period(i.agency_id,current_date); ref:='JE-INV-'||replace(i.id::text,'-',''); if exists(select 1 from public.journal_entries where agency_id=i.agency_id and reference=ref) then return (select id from public.journal_entries where agency_id=i.agency_id and reference=ref limit 1); end if; select id into ar from public.chart_of_accounts where agency_id=i.agency_id and code=case when coalesce(i.total_sar,0)>0 and coalesce(i.total_dzd,0)=0 then '1201' else '1200' end limit 1; select id into rev from public.chart_of_accounts where agency_id=i.agency_id and code=case when coalesce(i.total_sar,0)>0 and coalesce(i.total_dzd,0)=0 then '4001' else '4000' end limit 1; insert into public.journal_entries(agency_id,branch_id,fiscal_period_id,reference,description,source_type,source_id,created_by) values(i.agency_id,coalesce(i.branch_id,i.branch_uuid),fp,ref,'Invoice posted','INVOICE',i.id,auth.uid()) returning id into je; if coalesce(i.total_dzd,0)>0 then insert into public.journal_lines(journal_entry_id,agency_id,branch_id,account_id,currency_code,debit,credit,memo) values(je,i.agency_id,coalesce(i.branch_id,i.branch_uuid),ar,'DZD',i.total_dzd,0,'Accounts receivable'),(je,i.agency_id,coalesce(i.branch_id,i.branch_uuid),rev,'DZD',0,i.total_dzd,'Revenue'); end if; if coalesce(i.total_sar,0)>0 then insert into public.journal_lines(journal_entry_id,agency_id,branch_id,account_id,currency_code,debit,credit,memo) values(je,i.agency_id,coalesce(i.branch_id,i.branch_uuid),ar,'SAR',i.total_sar,0,'Accounts receivable'),(je,i.agency_id,coalesce(i.branch_id,i.branch_uuid),rev,'SAR',0,i.total_sar,'Revenue'); end if; perform public.assert_journal_balanced(je); return je; end; $$;
revoke all on function public.require_finance_aal2() from public,anon,authenticated;
revoke all on function public.create_invoice_transaction(uuid,text) from public,anon; grant execute on function public.create_invoice_transaction(uuid,text) to authenticated;
revoke all on function public.reverse_payment_transaction(uuid,numeric,numeric,text) from public,anon; grant execute on function public.reverse_payment_transaction(uuid,numeric,numeric,text) to authenticated;
revoke all on function public.post_invoice_journal(uuid) from public,anon; grant execute on function public.post_invoice_journal(uuid) to authenticated;
